import{_ as a,o as r,c as t,ae as o}from"./chunks/framework.Dh1jimFm.js";const h=JSON.parse('{"title":"CafeTran Workflow","description":"","frontmatter":{},"headers":[],"relativePath":"cat-tools/cafetran.md","filePath":"cat-tools/cafetran.md"}'),l={name:"cat-tools/cafetran.md"};function n(i,e,s,c,f,p){return r(),t("div",null,e[0]||(e[0]=[o('<h1 id="cafetran-workflow" tabindex="-1">CafeTran Workflow <a class="header-anchor" href="#cafetran-workflow" aria-label="Permalink to &quot;CafeTran Workflow&quot;">​</a></h1><p>Supervertaler supports CafeTran bilingual table DOCX workflows.</p><h2 id="export-from-cafetran" tabindex="-1">Export from CafeTran <a class="header-anchor" href="#export-from-cafetran" aria-label="Permalink to &quot;Export from CafeTran&quot;">​</a></h2><ol><li>Open your project in CafeTran</li><li>Go to <strong>Project → Export → Bilingual Table</strong></li><li>Choose <strong>DOCX</strong> format</li></ol><h2 id="import-to-supervertaler" tabindex="-1">Import to Supervertaler <a class="header-anchor" href="#import-to-supervertaler" aria-label="Permalink to &quot;Import to Supervertaler&quot;">​</a></h2><ol><li>In Supervertaler: <strong>File → Open</strong> and select the exported DOCX</li><li>Translate and review in the grid</li><li>Confirm segments when ready (<code>Ctrl+Enter</code>)</li></ol><h2 id="export-back-to-cafetran" tabindex="-1">Export back to CafeTran <a class="header-anchor" href="#export-back-to-cafetran" aria-label="Permalink to &quot;Export back to CafeTran&quot;">​</a></h2><ol><li>In Supervertaler: <strong>File → Export → CafeTran Bilingual DOCX</strong></li><li>Save the file</li></ol><h2 id="reimport-to-cafetran" tabindex="-1">Reimport to CafeTran <a class="header-anchor" href="#reimport-to-cafetran" aria-label="Permalink to &quot;Reimport to CafeTran&quot;">​</a></h2><ol><li>In CafeTran: <strong>Project → Import</strong> and select the bilingual table</li><li>Choose merge options as needed</li></ol><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Preserve pipe-style markers and any CAT tags.</li><li>Don’t change the bilingual table structure in Word.</li></ul>',12)]))}const u=a(l,[["render",n]]);export{h as __pageData,u as default};
